@@ -50,0 +50,47 @@
+  static void gatherScatter32(C2_MacroAssembler* masm, bool is_store,
+                              VectorRegister reg, VectorRegister idx, VectorRegister offsets,
+                              BasicType bt, Register base, uint vector_length,
+                              Assembler::VectorMask vm = Assembler::unmasked) {
+    assert(type2aelembytes(bt) == 4, "32-bit vector elements required");
+    const uint shift = 2;
+    __ vsetvli_helper(bt, vector_length);
+    __ vsll_vi(offsets, idx, shift);
+
+    if (is_store) {
+      __ vsuxei32_v(reg, base, offsets, vm);
+    } else {
+      if (vm == Assembler::v0_t) {
+        __ vmv_v_i(reg, 0);
+      }
+      __ vluxei32_v(reg, base, offsets, vm);
+    }
+  }
+
+  static void gatherScatter64(C2_MacroAssembler* masm, bool is_store,
+                              VectorRegister reg, VectorRegister idx, VectorRegister offsets,
+                              BasicType bt, Register base, uint vector_length,
+                              Assembler::VectorMask vm = Assembler::unmasked) {
+    assert(type2aelembytes(bt) == 8, "64-bit vector elements required");
+    // Scale indices by 8 to obtain byte offsets for 64-bit elements.
+    const uint shift = 3;
+    if (UseZvbb) {
+      __ vsetvli_helper(T_INT, vector_length, Assembler::mf2);
+      __ vwsll_vi(offsets, idx, shift);
+      // Indexed accesses use SEW for data width; e64,m1 preserves VLMAX.
+      __ vsetvli_helper(bt, vector_length);
+    } else {
+      __ vsetvli_helper(bt, vector_length);
+      __ vzext_vf2(offsets, idx);
+      __ vsll_vi(offsets, offsets, shift);
+    }
+
+    if (is_store) {
+      __ vsuxei64_v(reg, base, offsets, vm);
+    } else {
+      if (vm == Assembler::v0_t) {
+        __ vmv_v_i(reg, 0);
+      }
+      __ vluxei64_v(reg, base, offsets, vm);
+    }
+  }
